DECLARE p jsonb := $payload${"ley":{"id":"373ce6df-4e78-59d9-aae5-54007a446c59","titulo":"Acuerdo por el que se emite la modificación a la Convocatoria para la Atención de Proyectos Estratégicos de Generación y Almacenamiento de Energía Eléctrica, alineados a la planeación vinculante [DOF 26/05/2026]","siglas":"CONV-ESTRATEGICOS-M1","fecha_publicacion":"2026-05-26","fecha_ultima_reforma":null,"vigente":null,"temas_clave":["Proyectos estratégicos de generación y almacenamiento","Convocatorias","Modificación","Interconexión"],"url_original":"https://sidof.segob.gob.mx/notas/docFuente/5788508","tipo":"acuerdo"},"articulos":[{"id":"2d20afe0-6f04-545b-bf6f-9251561c578b","ley_id":"373ce6df-4e78-59d9-aae5-54007a446c59","orden":0,"identificador":"Nota editorial · versiones relacionadas","contenido":"### Nota editorial · versión publicada y documentos relacionados\n\nEste registro reproduce la publicación del DOF de 26/05/2026. Se conserva el texto de esa publicación; las modificaciones se consultan en registros separados. No es un texto consolidado ni una indicación de que todos sus plazos permanezcan abiertos.\n\nDocumentos de la misma convocatoria incorporados al acervo:\n\n- <a href=\"/#ley-24110e92-4d4c-5434-b02a-6a1794ee65ff\" target=\"_blank\" rel=\"noopener noreferrer\">Texto original · 15/05/2026</a> · [fuente oficial](https://sidof.segob.gob.mx/notas/docFuente/5787666)\n- <a href=\"/#ley-373ce6df-4e78-59d9-aae5-54007a446c59\" target=\"_blank\" rel=\"noopener noreferrer\">Modificación 1 · 26/05/2026</a> · [fuente oficial](https://sidof.segob.gob.mx/notas/docFuente/5788508)\n- <a href=\"/#ley-29886758-c194-5db4-86eb-8c96347f7aba\" target=\"_blank\" rel=\"noopener noreferrer\">Modificación 2 · 10/07/2026</a> · [fuente oficial](https://sidof.segob.gob.mx/notas/docFuente/5793261)\n- <a href=\"/#ley-372339cc-7ed9-5e5c-8023-647e1a12c3b6\" target=\"_blank\" rel=\"noopener noreferrer\">Modificación 3 · 02/09/2026</a> · [fuente oficial](https://sidof.segob.gob.mx/notas/docFuente/5797703)\n\nEsta nota es información editorial del buscador y no forma parte de la publicación oficial. Referencias del radar con corte al 14 de septiembre de 2026, cotejadas para esta incorporación.\n","tipo_articulo":"complementario","titulo_nombre":"Información editorial de la versión","capitulo_nombre":null,"seccion_nombre":null},{"id":"3d055497-38c8-57d5-9c38-614a69fca4f8","ley_id":"373ce6df-4e78-59d9-aae5-54007a446c59","orden":1,"identificador":"Preámbulo del acuerdo modificatorio","contenido":"<!-- ### Transcripción de la publicación oficial -->\n\n ACUERDO por el que se emite la modificación a la Convocatoria para la Atención de Proyectos Estratégicos de Generación y Almacenamiento de Energía Eléctrica, alineados a la planeación vinculante.\n Al margen un sello con el Escudo Nacional, que dice: Estados Unidos Mexicanos.- Secretaría de Energía.\n<div> LUZ ELENA GONZÁLEZ ESCOBAR, Secretaria de Energía, con fundamento en lo dispuesto por los artículos 28, párrafo noveno, 90, párrafo primero, de la Constitución Política de los Estados Unidos Mexicanos; 2, fracción I, 14, párrafo primero, 26, fracción IX y 33, fracciones I, IV, V, XXIX y XXXIII de la Ley Orgánica de la Administración Pública Federal; 4 de la Ley Federal de Procedimiento Administrativo; 2, 10 fracción I y XIV, 16, 36 y 38 de la Ley del Sector Eléctrico; 57 del Reglamento de la Ley de Planeación y Transición Energética; 2, fracción XXV, 3 y 13 del Reglamento de la Ley del Sector Eléctrico, y</div>\n<div> CONSIDERANDO<br> </div>\n<div> Que el 15 de mayo de 2026, se publicó en el Diario Oficial de la Federación la &quot;CONVOCATORIA PARA LA ATENCIÓN DE PROYECTOS ESTRATÉGICOS DE GENERACIÓN Y ALMACENAMIENTO DE ENERGÍA ELÉCTRICA, ALINEADOS A LA PLANEACIÓN VINCULANTE&quot;, dirigida a las personas interesadas en desarrollar proyectos estratégicos de generación y almacenamiento de energía eléctrica alineados a la planeación vinculante del sector eléctrico.</div>\n<div> Que la Convocatoria establece el mecanismo para la atención prioritaria de las solicitudes para la obtención de permisos, los estudios de interconexión y conexión y, en su caso, la celebración de los contratos de interconexión y conexión, que permita el desarrollo de proyectos estratégicos que se requieran para fortalecer la confiabilidad, continuidad, eficiencia, seguridad y sostenibilidad del SEN.</div>\n<div> Que derivado del interés manifestado por las personas participantes y con el propósito de favorecer una mayor participación en la Convocatoria, se considera oportuno modificar las fechas y plazos previstos en el calendario contenido en la Convocatoria, por lo que he tenido a bien emitir el siguiente:</div>\n<div> ACUERDO POR EL QUE SE EMITE LA MODIFICACIÓN A LA CONVOCATORIA  PARA LA ATENCIÓN<br> DE PROYECTOS ESTRATÉGICOS DE GENERACIÓN Y ALMACENAMIENTO DE ENERGÍA ELÉCTRICA,<br> ALINEADOS A LA PLANEACIÓN VINCULANTE<br> </div>","tipo_articulo":"preambulo","titulo_nombre":"Proyectos estratégicos de generación y almacenamiento · publicación del 26-05-2026","capitulo_nombre":null,"seccion_nombre":null},{"id":"1946cddc-6318-5768-bc1c-8a59afa420ed","ley_id":"373ce6df-4e78-59d9-aae5-54007a446c59","orden":2,"identificador":"Resolutivo PRIMERO","contenido":"<!-- ### Transcripción de la publicación oficial -->\n\n<div> PRIMERO. Se modifica la Etapa 2 del numeral 17.1 de la Convocatoria para la Atención de Proyectos Estratégicos de Generación y Almacenamiento de Energía Eléctrica, alineados a la planeación vinculante, para quedar en los siguientes términos:</div>\n<div> &quot;</div>\n<div> 17.1 ...</div>\n<div> ...</div>\n<table> <tbody><tr> <td> <div> No. de<br> Etapa<br> </div> </td> <td> <div> Alcance<br> </div> </td> <td> <div> Fechas/plazos (días<br> hábiles)<br> </div> </td> <td> <div> Descripción de la actividad<br> </div> </td> </tr> <tr> <td> <div> 2<br> </div> </td> <td> <div> Registro de manifestación de interés y solicitud de estudios de interconexión y conexión.</div> </td> <td> <div> 2 de junio al 2 de<br> septiembre de 2026<br> </div> </td> <td> <div> La persona solicitante debe registrar su manifestación de interés y la solicitud de estudios de conexión e interconexión, según corresponda, a través de la VUPE en el formato previsto para tales efectos.</div> </td> </tr> </tbody></table>\n<div> ...&quot;</div>","tipo_articulo":"ordinario","titulo_nombre":"Proyectos estratégicos de generación y almacenamiento · publicación del 26-05-2026","capitulo_nombre":"Resolutivo PRIMERO del acuerdo modificatorio","seccion_nombre":null},{"id":"06901cca-b1f9-562c-bb97-f7c40d7ca08b","ley_id":"373ce6df-4e78-59d9-aae5-54007a446c59","orden":3,"identificador":"Resolutivo SEGUNDO","contenido":"<!-- ### Transcripción de la publicación oficial -->\n\n<div> SEGUNDO. Los plazos y referencias contenidas en la Convocatoria para la Atención de Proyectos Estratégicos de Generación y Almacenamiento de Energía Eléctrica, alineados a la planeación vinculante, deben entenderse conforme a lo previsto en la modificación a que se refiere el numeral anterior.</div>","tipo_articulo":"ordinario","titulo_nombre":"Proyectos estratégicos de generación y almacenamiento · publicación del 26-05-2026","capitulo_nombre":"Resolutivo SEGUNDO del acuerdo modificatorio","seccion_nombre":null},{"id":"6a0a2e89-c92d-5a57-bd28-d9511e2ddba4","ley_id":"373ce6df-4e78-59d9-aae5-54007a446c59","orden":4,"identificador":"Transitorio ÚNICO · acuerdo","contenido":"<!-- ### Transcripción de la publicación oficial -->\n\n<div> TRANSITORIO<br> </div>\n<div> ÚNICO. El presente Acuerdo entrará en vigor el mismo día de su publicación en el Diario Oficial  de la Federación.</div>","tipo_articulo":"transitorio","titulo_nombre":"Proyectos estratégicos de generación y almacenamiento · publicación del 26-05-2026","capitulo_nombre":"Transitorios del acuerdo modificatorio","seccion_nombre":null},{"id":"5c884b0d-aa9a-50da-8d53-8e0e913f1a66","ley_id":"373ce6df-4e78-59d9-aae5-54007a446c59","orden":5,"identificador":"Firma del acuerdo","contenido":"<!-- ### Transcripción de la publicación oficial -->\n\n<div> Ciudad de México, a 22 de mayo de 2026.- La Secretaria de Energía, Luz Elena González Escobar.- Rúbrica.</div>","tipo_articulo":"complementario","titulo_nombre":"Proyectos estratégicos de generación y almacenamiento · publicación del 26-05-2026","capitulo_nombre":"Documentos complementarios","seccion_nombre":null}],"temas":[{"nivel":"titulo","nombre":"Información editorial de la versión","orden":0},{"nivel":"capitulo","nombre":"Resolutivo PRIMERO del acuerdo modificatorio","orden":1},{"nivel":"capitulo","nombre":"Resolutivo SEGUNDO del acuerdo modificatorio","orden":2},{"nivel":"capitulo","nombre":"Transitorios del acuerdo modificatorio","orden":3}],"fuente":{"name":"CONV-ESTRATEGICOS-M1","code":"5788508","radar":"RAD-037","familia":"Proyectos estratégicos de generación y almacenamiento","modificacion":1,"url":"https://sidof.segob.gob.mx/notas/docFuente/5788508","sha256":"1ac32a60c8f6aa1a4ccabaaf88c3c6018332d782eb7406ef80f3949681dc8b9b","fecha":"26-05-2026","titulo":"Acuerdo por el que se emite la modificación a la Convocatoria para la Atención de Proyectos Estratégicos de Generación y Almacenamiento de Energía Eléctrica, alineados a la planeación vinculante.","codDiario":327526,"pagina":45,"tables":1,"images":[]}}$payload$::jsonb; lid uuid;
BEGIN
 lid := (p->'ley'->>'id')::uuid;
 LOCK TABLE public.leyes,public.articulos,public.temas IN SHARE ROW EXCLUSIVE MODE;
 IF EXISTS(SELECT 1 FROM public.leyes WHERE id=lid OR lower(siglas)=lower(p->'ley'->>'siglas') OR lower(titulo)=lower(p->'ley'->>'titulo') OR url_original=p->'ley'->>'url_original') THEN RAISE EXCEPTION 'El instrumento ya existe: revisar, no reemplazar'; END IF;
 INSERT INTO public.leyes(id,titulo,siglas,fecha_publicacion,fecha_ultima_reforma,vigente,temas_clave,url_original,tipo) SELECT id,titulo,siglas,fecha_publicacion,fecha_ultima_reforma,vigente,temas_clave,url_original,tipo FROM jsonb_populate_record(null::public.leyes,p->'ley');
 INSERT INTO public.articulos(id,ley_id,identificador,contenido,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre,orden) SELECT id,ley_id,identificador,contenido,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre,orden FROM jsonb_populate_recordset(null::public.articulos,p->'articulos');
 INSERT INTO public.temas(ley_id,nivel,nombre,orden) SELECT lid,t->>'nivel',t->>'nombre',(t->>'orden')::int FROM jsonb_array_elements(p->'temas')t;
 IF (SELECT count(*)FROM public.articulos WHERE ley_id=lid)<>jsonb_array_length(p->'articulos') OR EXISTS(SELECT 1 FROM jsonb_array_elements(p->'articulos')b LEFT JOIN public.articulos a ON a.id=(b->>'id')::uuid WHERE a.id IS NULL OR (to_jsonb(a)-'fts'-'created_at') IS DISTINCT FROM b) THEN RAISE EXCEPTION 'Fallo de cotejo exacto de artículos'; END IF;
 IF (SELECT count(*)FROM public.temas WHERE ley_id=lid)<>jsonb_array_length(p->'temas') OR EXISTS(SELECT 1 FROM jsonb_array_elements(p->'temas')b WHERE NOT EXISTS(SELECT 1 FROM public.temas t WHERE ley_id=lid AND (to_jsonb(t)-'id'-'ley_id'-'created_at')=b)) THEN RAISE EXCEPTION 'Fallo de cotejo de estructura'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.leyes l WHERE id=lid AND to_jsonb(l)-'created_at'=p->'ley') THEN RAISE EXCEPTION 'Metadatos diferentes'; END IF;
 IF EXISTS(SELECT 1 FROM public.articulos WHERE ley_id=lid AND (nullif(trim(contenido),'')IS NULL OR fts IS NULL OR fts=''::tsvector)) THEN RAISE EXCEPTION 'Texto o índice FTS vacío'; END IF;
END $ingest$;
COMMIT;
SELECT l.siglas,l.id,(SELECT count(*)FROM public.articulos a WHERE a.ley_id=l.id)fragmentos,(SELECT count(*)FROM public.temas t WHERE t.ley_id=l.id)temas FROM public.leyes l WHERE l.id='373ce6df-4e78-59d9-aae5-54007a446c59';
